const controls=[...document.querySelectorAll('.explorer-trigger')];
const mobile=matchMedia('(max-width:650px)'), reduced=matchMedia('(prefers-reduced-motion:reduce)');
const valid=new Set(controls.map(c=>c.id.replace('trigger-','')));
function selected(){return controls.find(c=>c.getAttribute('aria-expanded')==='true')?.id.replace('trigger-','')||'closed';}
function select(name,{record=false,focus=false,reveal=false}={}){
 for(const c of controls){const active=c.id==='trigger-'+name;const panel=document.getElementById(c.getAttribute('aria-controls'));c.setAttribute('aria-expanded',String(active));panel.hidden=!active;}
 if(record){const url=new URL(location);url.searchParams.set('view',name);url.hash='explorer';history.pushState({explorer:name},'',url);}
 const control=document.getElementById('trigger-'+name);
 if(focus&&control)control.focus({preventScroll:true});
 if(reveal&&control)requestAnimationFrame(()=>{const rect=control.getBoundingClientRect();if(rect.top<16||rect.bottom>innerHeight-60)control.scrollIntoView({block:'start',behavior:reduced.matches?'instant':'smooth'});});
}
for(const control of controls)control.addEventListener('click',()=>{const name=control.id.replace('trigger-','');select(selected()===name?'closed':name,{record:true,reveal:true});if(selected()==='closed'&&control.getBoundingClientRect().top<0)control.scrollIntoView({block:'start',behavior:reduced.matches?'instant':'smooth'});});
function restore(){const name=new URL(location).searchParams.get('view');select(valid.has(name)||name==='closed'?name:'projects');}
addEventListener('popstate',restore);restore();
function arrange(){const region=document.querySelector('.explorer-content');if(!region)return;for(const c of controls){const panel=document.getElementById(c.getAttribute('aria-controls'));mobile.matches?c.after(panel):region.append(panel);}}
mobile.addEventListener('change',arrange);arrange();
for(const control of controls){const panel=document.getElementById(control.getAttribute('aria-controls'));panel.addEventListener('keydown',event=>{if(event.key==='Escape'){select('closed',{record:true});control.focus({preventScroll:true});control.scrollIntoView({block:'nearest',behavior:reduced.matches?'instant':'smooth'});}});const close=document.createElement('button');close.type='button';close.className='panel-close';close.textContent='Close '+control.textContent.replace('＋','').toLowerCase()+' ×';close.addEventListener('click',()=>{select('closed',{record:true});control.focus({preventScroll:true});control.scrollIntoView({block:'nearest',behavior:reduced.matches?'instant':'smooth'});});panel.append(close);}
const latest=document.querySelector('.latest-research');if(latest)latest.addEventListener('click',event=>{event.preventDefault();select('experiments',{record:true});const row=document.querySelector('#panel-experiments .update');row?.scrollIntoView({block:'center',behavior:reduced.matches?'instant':'smooth'});row?.querySelector('a')?.focus({preventScroll:true});});
const data=document.querySelector('#stage-data');if(data){const stages=JSON.parse(data.textContent);for(const button of document.querySelectorAll('[data-stage]'))button.addEventListener('click',()=>{for(const b of document.querySelectorAll('[data-stage]'))b.setAttribute('aria-pressed',String(b===button));const [name,text]=stages[+button.dataset.stage];document.querySelector('#stage-name').textContent=name;document.querySelector('#stage-text').textContent=text;});}
const filters=[...document.querySelectorAll('.filters select')];let limit=6;const more=document.querySelector('#load-more');
function filter(record=false){const [project,status,type]=filters.map(f=>f.value);let count=0;for(const row of document.querySelectorAll('.update')){const matches=(project==='All projects'||project===row.dataset.project)&&(status==='All statuses'||status===row.dataset.status)&&(type==='All update types'||type===row.dataset.type);if(matches)count++;row.hidden=!matches||count>limit;}document.querySelector('#result-count').textContent=count?`${Math.min(limit,count)} of ${count} research updates shown`:'No published updates in this selection.';if(more)more.hidden=count<=limit;if(record){const url=new URL(location);for(const f of filters){if(f.selectedIndex)url.searchParams.set(f.id,f.value);else url.searchParams.delete(f.id);}history.replaceState(null,'',url);}}
for(const f of filters){const value=new URL(location).searchParams.get(f.id);if([...f.options].some(o=>o.value===value))f.value=value;f.addEventListener('change',()=>{limit=6;filter(true);});}if(filters.length)filter();more?.addEventListener('click',()=>{limit+=6;filter();});document.querySelector('#reset-filters')?.addEventListener('click',()=>{filters.forEach(f=>f.selectedIndex=0);limit=6;filter(true);filters[0].focus();});
// Keep the optional engineering explanation visible on desktop and compact on mobile.
function arrangeProjectDetails(){for(const detail of document.querySelectorAll('details.ai-direction')){if(mobile.matches&&detail.contains(document.activeElement))detail.querySelector('summary').focus({preventScroll:true});detail.open=!mobile.matches;}}
arrangeProjectDetails();mobile.addEventListener('change',arrangeProjectDetails);
